const events = $items('Read Events 24h').map(i => i.json);
const now = Date.now();
const since = now - 24 * 3600 * 1000;
const recent = events.filter(e => {
  const t = Date.parse(e.created_at || e.timestamp || '');
  return t && t >= since;
});

if (recent.length === 0) return [];   // quiet day -> no mail, no ledger row

const recs = $items('Read Recipients').map(i => i.json)
  .filter(r => r.active === true || r.active === 'true' || r.active === 1);
const to = [...new Set(recs.map(r => r.email))].filter(e => e && e.includes('@')).join(',');
if (!to) return [];

// aggregate
const bySig = {}, bySrc = {}, byAgent = {}, drops = {};
for (const e of recent) {
  bySig[e.signature] = (bySig[e.signature] || 0) + 1;
  bySrc[e.src_ip] = (bySrc[e.src_ip] || 0) + 1;
  byAgent[e.agent_name] = (byAgent[e.agent_name] || 0) + 1;
  if (e.action === 'blocked') drops[e.signature] = (drops[e.signature] || 0) + 1;
}
const top = (o, n = 10) => Object.entries(o).sort((a, b) => b[1] - a[1]).slice(0, n);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rowsOf = (o) => top(o).map(([k, v]) =>
  `<tr><td style="padding:8px 14px;border-bottom:1px solid #1e293b;font-family:monospace;color:#e2e8f0">${esc(k)}</td><td style="padding:8px 14px;border-bottom:1px solid #1e293b;text-align:right;color:#94a3b8">${v}</td></tr>`).join('');

const today = $('Check Ledger Today').first().json.today;
const dropCount = Object.values(drops).reduce((a, b) => a + b, 0);

const html = `<!doctype html><html><body style="margin:0;background:#020617;font-family:Arial,Helvetica,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#020617;padding:24px">
<tr><td align="center"><table width="640" style="background:#0f172a;border:1px solid #1e293b;border-radius:12px;overflow:hidden">
<tr><td style="padding:20px 28px;background:#0f172a;border-bottom:1px solid #1e293b">
  <img src="https://www.agbcommunication.com/_next/static/media/AGBLogo.77b5873b.svg" height="38" style="float:left">
  <span style="float:right;color=${dropCount ? '#ef4444' : '#22c55e'};border:1px solid ${dropCount ? '#7f1d1d' : '#14532d'};background:${dropCount ? '#450a0a' : '#052e16'};border-radius:20px;padding:4px 14px;font-size:12px;font-weight:bold">${dropCount ? '⚠ ' + dropCount + ' PACKET DROPS' : '✓ NO DROPS'}</span>
  <div style="clear:both"></div></td></tr>
<tr><td style="padding:28px">
  <h2 style="color:#f8fafc;font-size:18px;margin:0 0 6px">Suricata IPS Daily Digest</h2>
  <p style="color:#64748b;font-size:13px;margin:0 0 24px">${today} · last 24 hours · ${recent.length} events across ${Object.keys(byAgent).length} agent(s)</p>
  <h3 style="color:#38bdf8;font-size:14px;border-bottom:1px solid #1e293b;padding-bottom:8px">Top Signatures</h3>
  <table width="100%" style="border-collapse:collapse;font-size:13px">${rowsOf(bySig)}</table>
  <h3 style="color:#38bdf8;font-size:14px;border-bottom:1px solid #1e293b;padding:18px 0 8px">Top Source IPs</h3>
  <table width="100%" style="border-collapse:collapse;font-size:13px">${rowsOf(bySrc)}</table>
  <h3 style="color:#38bdf8;font-size:14px;border-bottom:1px solid #1e293b;padding:18px 0 8px">Per-Agent</h3>
  <table width="100%" style="border-collapse:collapse;font-size:13px">${rowsOf(byAgent)}</table>
  ${dropCount ? `<h3 style="color:#ef4444;font-size:14px;border-bottom:1px solid #1e293b;padding:18px 0 8px">🔴 Packet Drops (NFQUEUE)</h3>
  <table width="100%" style="border-collapse:collapse;font-size:13px">${rowsOf(drops)}</table>` : ''}
  <p style="color:#475569;font-size:11px;margin-top:26px">Automated digest — AGB SOC · Suricata IPS fleet · reply TG group for instant alerts</p>
</td></tr></table></td></tr></table></body></html>`;

return [{ json: {
  toEmail: to,
  subject: `[AGB SOC] Suricata IPS Digest ${today} — ${recent.length} events${dropCount ? ', ' + dropCount + ' DROPS' : ''}`,
  html,
  count: recent.length,
  today
}}];

const j = $('Build Digest Mail').first().json;
return [{ json: {
  digest_date: j.today,
  status: 'sent',
  alert_count: Number(j.count || 0),
  sent_to: String(j.toEmail || '').slice(0, 300),
  sent_at: new Date().toISOString()
} }];

// same-day guard: today's ledger row with status 'sent' -> emit 0 items (flow stops)
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Yangon' });
const res = await this.helpers.httpRequest({
  url: 'http://127.0.0.1:5678/api/v1/data-tables/ryM0V3Lm7leKYpo7/rows?filter=' +
       encodeURIComponent(JSON.stringify({ "digest_date": { "$eq": today } })),
  headers: { 'X-N8N-API-KEY': '<API_KEY_AT_DEPLOY>' },
  json: true
});
const rows = res.data || [];
if (rows.some(r => ((r.data || r).status) === 'sent')) {
  console.log('digest already sent today — skipping');
  return [];
}
return [{ json: { today } }];
